pub(crate) const STYLES: &str = r#"
.df-sheet{--gold:#d9b77a;--ink:#141310;--muted:#b4aca0;position:relative;isolation:isolate;min-height:100svh;background:var(--ink);color:#f4eddf;font:15px/1.65 system-ui,sans-serif;overflow:hidden}.df-sheet *{box-sizing:border-box;min-width:0}.df-sheet [hidden]{display:none!important}.df-sheet p,.df-sheet h1,.df-sheet h2,.df-sheet button,.df-sheet dt,.df-sheet dd{overflow-wrap:anywhere}.df-sheet .sheet-art{position:absolute;inset:0;width:100%;height:620px;object-fit:cover;object-position:center 43%;z-index:-3}.df-sheet:before{content:'';position:absolute;inset:0;z-index:-2;background:linear-gradient(180deg,#14131055,#14131020 130px,#141310c9 370px,#141310 620px),linear-gradient(90deg,#11100da6,transparent 75%)}
.df-sheet .sheet-header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:22px 4vw;border-bottom:1px solid #d9b77a24;background:linear-gradient(#11100a99,transparent)}.df-sheet .sheet-brand{color:#efce91;font:26px Georgia,serif;letter-spacing:-1px}.df-sheet .sheet-connection{color:#d8cbb2;font:11px/1.6 system-ui,sans-serif;letter-spacing:.7px;margin:0;max-width:45%;text-align:right}.df-sheet .sheet-hero{width:min(1180px,92%);margin:0 auto;padding:74px 0 30px}.df-sheet .sheet-identity{font:10px/1.7 system-ui,sans-serif;letter-spacing:2.5px;text-transform:uppercase;color:var(--gold);margin:0 0 12px}.df-sheet h1{font:400 clamp(40px,5.5vw,68px)/1.08 Georgia,serif;letter-spacing:-1.8px;margin:0 0 15px;max-width:850px;text-shadow:0 3px 30px #000}.df-sheet .sheet-subtitle{font:17px/1.65 Georgia,serif;color:#eee5d5;max-width:650px;margin:0;text-shadow:0 2px 8px #000}.df-sheet .sheet-art-fallback{color:#d8cbb2;font:12px/1.6 system-ui,sans-serif;padding:10px 13px;border-left:2px solid var(--gold);background:#24211bee;max-width:650px}.df-sheet .sheet-notice{width:min(1180px,92%);margin:0 auto 18px;padding:11px 16px;border:1px solid #c7a86b3d;border-left:3px solid #d9b77a;border-radius:0 6px 6px 0;background:linear-gradient(90deg,#30291fed,#1c1a15e6);color:#e5d6b8;font-size:12px}
.df-sheet .sheet-workspace{width:min(1180px,92%);margin:0 auto 48px;padding:24px 28px 30px;border:1px solid #c7a86b4d;border-radius:10px;background:linear-gradient(135deg,#24211bf2,#181713f7);box-shadow:0 16px 45px #0004}.df-sheet .sheet-tabs{display:flex;flex-wrap:wrap;gap:8px;border-bottom:1px solid #d9b77a30;padding:0 0 18px}.df-sheet button{font:13px/1.5 system-ui,sans-serif;min-height:48px;max-width:100%;border:1px solid #a98b574d;border-radius:6px;padding:11px 16px;background:#29251e;color:#ede2cb;cursor:pointer;white-space:normal;touch-action:manipulation;box-shadow:inset 0 1px 0 #fff1}.df-sheet .sheet-tabs button{flex:1 1 120px;background:#15151199;color:#c5b99e}.df-sheet button:hover:enabled{border-color:#e5bd77;background:#42382a;color:#f4eddf}.df-sheet .sheet-tabs button[aria-selected=true]{border-color:#e9c78d;background:linear-gradient(135deg,#e3c592,#b99151);color:#211b11;font-weight:650;box-shadow:0 5px 20px #9f6b3026,inset 0 1px 0 #fff6}.df-sheet .sheet-tabs button[aria-selected=true]:hover:enabled{background:#edcea0}.df-sheet button:disabled{color:#aaa194;border-color:#8c806b3d;background:#1d1c17;cursor:default;box-shadow:none}.df-sheet button[aria-busy=true]{border-style:dashed}.df-sheet :focus-visible{outline:3px solid #f1d69b;outline-offset:4px}.df-sheet .sheet-filter{display:grid;gap:7px;margin:20px 0 26px;font-size:12px;color:#c5b99e;max-width:440px}.df-sheet .sheet-filter label{display:grid;gap:7px}.df-sheet .sheet-filter input{font:16px/1.5 system-ui,sans-serif;color:#f4eddf;background:#161510;border:1px solid #a3916b70;border-radius:6px;padding:10px 13px;min-height:48px;width:100%;box-shadow:inset 0 2px 6px #0003}.df-sheet .sheet-filter input:hover{border-color:#cba466}.df-sheet .sheet-filter p{margin:0;color:#dcc393}
.df-sheet .sheet-tab-panel{display:grid;gap:28px}.df-sheet h2{font:400 26px/1.3 Georgia,serif;color:#e8d7b3;margin:0 0 6px}.df-sheet .sheet-caption{font-size:12px;color:var(--muted);margin:0 0 16px;max-width:750px}.df-sheet .sheet-rows{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;align-items:start}.df-sheet .sheet-row{border:1px solid #a394714d;background:linear-gradient(135deg,#30291f80,#151511b3);border-radius:8px;min-width:0;box-shadow:0 5px 16px #0002}.df-sheet .sheet-row:hover{border-color:#c7a86b80}.df-sheet .sheet-row[open]{border-color:#cba46680;background:linear-gradient(135deg,#39302566,#1c1a15)}.df-sheet .sheet-row-heading{padding:17px 18px;min-height:64px;cursor:pointer;position:relative;display:flex;align-items:center;gap:13px;list-style:none}.df-sheet .sheet-row-heading::-webkit-details-marker{display:none}.df-sheet .sheet-row-heading:before{content:'+';font:18px/1 Georgia,serif;color:#dfbd80;flex:0 0 25px;height:25px;display:grid;place-items:center;border:1px solid #cba46659;border-radius:50%;background:#15151180}.df-sheet .sheet-row[open] .sheet-row-heading:before{content:'−';background:#cba4661f}.df-sheet .sheet-row-title{font:18px/1.4 Georgia,serif;color:#f0e4cc;flex:1;overflow-wrap:anywhere}.df-sheet .sheet-row-value{font:12px/1.5 system-ui,sans-serif;color:#e4c58d;text-align:right;max-width:45%;overflow-wrap:anywhere}.df-sheet .sheet-row[open] .sheet-row-heading{border-bottom:1px solid #d9b77a24}.df-sheet .sheet-row-body{padding:16px 18px 20px}.df-sheet .sheet-row-summary{margin:0 0 17px;color:#d8cbb2;font-size:13px;overflow-wrap:anywhere}.df-sheet .sheet-fields{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:0 16px;font-size:12px;margin:0;border-top:1px solid #d9b77a24}.df-sheet dt{color:#b4a68e;padding:10px 0;border-bottom:1px solid #d9b77a24}.df-sheet dd{color:#eee5d5;margin:0;padding:10px 0;border-bottom:1px solid #d9b77a24;overflow-wrap:anywhere}.df-sheet .sheet-actions{display:flex;flex-wrap:wrap;gap:9px;margin-top:18px}.df-sheet .sheet-actions:empty{display:none}.df-sheet .sheet-actions button:enabled{color:#211b11;border-color:#e9c78d;background:linear-gradient(135deg,#e3c592,#b99151);font-weight:650;box-shadow:0 5px 20px #9f6b3026,inset 0 1px 0 #fff6}.df-sheet .sheet-actions button:hover:enabled{background:#edcea0}.df-sheet .sheet-empty{color:#c5b99e;text-align:center;padding:28px 20px;border:1px dashed #b69b6355;border-radius:8px;background:#15151180}
@media(max-width:700px){.df-sheet .sheet-header{padding:16px 5%;align-items:start;gap:14px}.df-sheet .sheet-brand{font-size:22px}.df-sheet .sheet-connection{max-width:46%;font-size:10px;letter-spacing:.3px}.df-sheet .sheet-hero{width:90%;padding:35px 0 21px}.df-sheet .sheet-identity{font-size:9px;letter-spacing:2px;margin-bottom:9px}.df-sheet h1{font-size:37px;letter-spacing:-1px;margin-bottom:11px}.df-sheet .sheet-subtitle{font-size:14px;line-height:1.6}.df-sheet .sheet-notice{width:90%;padding:10px 12px;margin-bottom:14px;font-size:11px}.df-sheet .sheet-workspace{padding:17px 16px 22px;width:90%;border-radius:8px;margin-bottom:28px}.df-sheet .sheet-tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;padding-bottom:16px}.df-sheet .sheet-tabs button{padding:10px 7px;font-size:12px;min-height:46px}.df-sheet .sheet-rows{grid-template-columns:1fr;gap:12px}.df-sheet .sheet-filter{max-width:none;margin:17px 0 22px}.df-sheet h2{font-size:23px}.df-sheet .sheet-caption{font-size:11px;margin-bottom:14px}.df-sheet .sheet-row-heading{padding:14px 12px;gap:10px;flex-wrap:wrap}.df-sheet .sheet-row-heading:before{flex-basis:23px;height:23px}.df-sheet .sheet-row-title{font-size:17px;flex-basis:calc(100% - 33px)}.df-sheet .sheet-row-value{font-size:12px;max-width:none;text-align:left;flex-basis:100%;margin-left:33px;color:#ddc28e}.df-sheet .sheet-row-body{padding:14px 14px 18px}.df-sheet .sheet-fields{grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:0 12px}.df-sheet .sheet-actions button{width:100%;min-height:46px;font-size:12px}.df-sheet .sheet-art{height:440px;object-position:48% center}.df-sheet:before{background:linear-gradient(180deg,#14131055,#14131030 110px,#141310d9 300px,#141310 440px),linear-gradient(90deg,#11100d66,transparent)}.df-sheet .sheet-empty{padding:23px 14px}}
@media(max-width:360px){.df-sheet .sheet-brand{font-size:20px}.df-sheet .sheet-connection{font-size:9px}.df-sheet .sheet-hero{padding-top:29px}.df-sheet h1{font-size:33px}.df-sheet .sheet-workspace{padding:15px 13px 20px}.df-sheet .sheet-tabs{grid-template-columns:repeat(2,minmax(0,1fr))}.df-sheet .sheet-tabs button:last-child{grid-column:1 / -1}.df-sheet .sheet-fields{grid-template-columns:minmax(0,1fr);gap:0}.df-sheet dt{border-bottom:0;padding:9px 0 2px}.df-sheet dd{padding:0 0 9px}}
@media(prefers-reduced-motion:reduce){.df-sheet *,.df-sheet *:before,.df-sheet *:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
"#;
